#pragma once
/**
 * @file NetworkPhaseColourCarry.hpp
 * @brief The phase-colour carry family (card LGM): the in-block columns and the record and birth rows.
 *
 * A family file of PASS B's station build (card NOM3 step PB1b): the steps of the family in
 * kStationBuildSteps / kStationCarrySteps (network/assembly/NetworkStationBuild.hpp), generated by
 * scripts/nom_pb1b_cut.py from the frozen text of networkPassB_'s produce loop.
 *
 * The harvest half (card NOM3 step HV1; generated by scripts/nom_hv1_cut.py, checked by
 * scripts/nom_hv1_verify.py) is the family's post-solve harvest, stash and prune, called by
 * networkHarvestLocalCarries (network/carry/NetworkLocalCarryHarvest.hpp, its table of contents).
 */

#include <cstdint>
#include <cstddef>
#include <vector>

namespace GnssProcessor {

struct EpochEvents;   // network/driver/NetworkEpoch.hpp

struct NetworkRunEndView;

// ---- PASS B station steps, declarations (card NOM3 step PB1b; generated by scripts/nom_pb1b_cut.py) ----

struct StationBuild;                       // network/assembly/NetworkStationBuild.hpp (card NOM3 step PB1b)
struct StationCarryFrame;                  // network/assembly/NetworkStationBuild.hpp
enum class StationStep : std::uint8_t;     // network/assembly/NetworkStationBuild.hpp

/**
 * @brief Card LGM: the phase-colour columns' record and birth rows.
 *
 * Step `phase_colour_rows` of kStationBuildSteps (network/assembly/NetworkStationBuild.hpp); its kinds:
 * PhaseColourBirth, PhaseColourBackstop. It returns at once unless `ctx.knobs.pc_on`. Records:
 * pl_pc, pc_birth_rows, pc_backstop_rows. The frozen text of networkPassB_'s produce loop below
 * its bindings (card NOM3 step PB1b).
 * @param build One station's build: the station and its slot writable, the run read only.
 * @return StationStep::Next.
 */
StationStep networkPhaseColourRows(StationBuild& build);

/**
 * @brief Card LGM: the station's carried phase-colour columns for the local block.
 *
 * Step `phase_colour_block` of kStationCarrySteps (network/assembly/NetworkStationBuild.hpp); its kinds:
 * none (it records only). It returns at once unless the frozen enclosing conditions
 * legacy_local_inject && do_amb_carry. Records: pc_planned; pc_bc, pc_pred. The frozen text of
 * networkPassB_'s produce loop below its bindings (card NOM3 step PB1b).
 * @param carry The station's carry frame (the build, the priors, the coupling builder, the
 *              block columns).
 */
void networkPhaseColourBlockColumns(StationCarryFrame& carry);

// ---- End of the PASS B station steps, declarations (card NOM3 step PB1b) ----

// ---- Harvest half, declarations (card NOM3 step HV1; generated by scripts/nom_hv1_cut.py) ----

struct NetworkRun;                          // network/driver/NetworkRun.hpp
struct NetworkEpoch;                        // network/driver/NetworkEpoch.hpp
struct HarvestBorder;                       // network/carry/NetworkLocalCarryHarvest.hpp
struct StationHarvestBlock;                 // network/carry/NetworkLocalCarryHarvest.hpp

/**
 * @brief Card LGM: each phase-colour column's posterior, regression and F3 row, and its trace row.
 *        No-op unless the station carries phase-colour columns under the coupling carry.
 *
 * @param run The run: its context (carry, counters, knobs), setup (stations) and engines.
 * @param ep This epoch after the solve (the solution, the assembly, the columns and the clock are
 *           read; nothing is written).
 * @param border This harvest's shared border (column identities, datum-frame covariance, the clone
 *               and shared-history handles).
 * @param sb Station @p i's harvest layout (its block columns, segment rows, back-substituted locals
 *           and F3 block).
 * @param i The station index.
 * @param events The epoch's events; writes harvest (the buffered rows).
 */
void networkHarvestPhaseColourStation(NetworkRun& run, const NetworkEpoch& ep,
                                      HarvestBorder& border, const StationHarvestBlock& sb,
                                      std::size_t i, EpochEvents& events);

/**
 * @brief Card LGM: drop phase-colour entries past network.phase_colour_max_gap_s (counted).
 *
 * @param run The run: its context (carry, counters, knobs), setup (stations) and engines.
 * @param ep This epoch after the solve (the solution, the assembly, the columns and the clock are
 *           read; nothing is written).
 */
void networkPrunePhaseColour(NetworkRun& run, const NetworkEpoch& ep);

// ---- End of the harvest half, declarations ----

/**
 * @brief Run-end report: the phase-colour state (LGM).
 *
 * The phase-colour state's edges (card LGM): births, carried folds, harvests and erases.
 *
 * Gate: returns 0 at once unless `ctx.knobs.pc_on`.
 *
 * @param v The run at its end (network/runend/NetworkRunEnd.hpp).
 * @return 0 (this report does not set the exit code).
 */
int networkPhaseColourRunEnd(const NetworkRunEndView& v);

} // namespace GnssProcessor
